 const save=()=>fs.writeFileSync(process.env.ISOLATION_REPORT,JSON.stringify(r,null,2));
 try {
  const ext=vscode.extensions.getExtension('phfsantos.markdown-editor');
  await ext.activate();r.activated=ext.isActive;save();
  const uri=vscode.Uri.joinPath(vscode.workspace.workspaceFolders[0].uri,'control.txt');
  fs.writeFileSync(uri.fsPath,'Host control.\n');
  const t=Date.now();let timer;
  try {const doc=await Promise.race([vscode.workspace.openTextDocument(uri),new Promise((_,rej)=>timer=setTimeout(()=>rej(Error('file open timeout')),6000))]);r.open={text:doc.getText(),dirty:doc.isDirty,version:doc.version};}finally{clearTimeout(timer);r.elapsedMs=Date.now()-t;}
 }catch(e){r.error=String(e.stack||e);}
 r.done=true;save();
};

